import smbus2
import time
import logging

# Configure logging for the ADS1015 driver
logging.basicConfig(level=logging.INFO, format="%(asctime)s - %(levelname)s - %(message)s")

# I2C address and register definitions for the ADS1015
ADS1015_ADDRESS = 0x48
ADS1015_REG_CONVERSION = 0x00
ADS1015_REG_CONFIG = 0x01

# Power-on configuration register values
POWER_ON_REGISTER = 0x02
CONFIG_REGISTER = 0x03


class ADS1015:
    """Driver for the Texas Instruments ADS1015 12-bit ADC."""

    def __init__(self, address=ADS1015_ADDRESS, busnum=1, debug=False):
        """Initialize the ADC driver."""
        self.address = address
        self.busnum = busnum
        self.debug = debug
        self.bus = smbus2.SMBus(self.busnum)

    def _read_register(self, register):
        """Read a single byte from the specified register."""
        try:
            return self.bus.read_byte_data(self.address, register)
        except IOError as e:
            if self.debug:
                logging.error(f"I2C read error: {e}")
            raise

    def _write_register(self, register, value):
        """Write a single byte to the specified register."""
        try:
            self.bus.write_byte_data(self.address, register, value)
        except IOError as e:
            if self.debug:
                logging.error(f"I2C write error: {e}")
            raise

    def _swap_endian(self, word):
        """Swap endianness of a 16-bit word."""
        return ((word & 0xff00) >> 8) | ((word & 0x00ff) << 8)


    def begin(self):
        """Power on the ADS1015 and configure for continuous conversion mode."""
        try:
            self._write_register(CONFIG_REGISTER, 0x8000)  # Continuous conversion
            time.sleep(0.001)  # Wait for conversion to start
            self._write_register(CONFIG_REGISTER, 0x0083)  # 12-bit, single-ended, A0 input
            logging.info("ADS1015 began successfully.")
        except IOError as e:
            if self.debug:
                logging.error(f"ADS1015 begin error: {e}")
            raise

    def close(self):
        """Close the I2C bus."""
        try:
            self.bus.close()
            logging.info("I2C bus closed.")
        except Exception as e:
            if self.debug:
                logging.error(f"Error closing bus: {e}")


    def read_adc_single_ended(self, channel=0, pga=6144, sps=250):
        """Read a single-ended ADC channel value."""
        try:
            # Build the configuration register value
            config = 0x4000 | (channel << 12) | (self._swap_endian(pga) << 9) | sps
            self._write_register(ADS1015_REG_CONFIG, config)

            # Wait for conversion to complete
            while True:
                status = self._read_register(ADS1015_REG_CONFIG)
                if (status & 0x8000) == 0:
                    break
                time.sleep(0.001)

            result = self._read_register(ADS1015_REG_CONVERSION)
            return result
        except IOError as e:
            if self.debug:
                logging.error(f"ADS1015 read error: {e}")
            raise

    def get_last_conversion_results(self):
        """Return the last ADC conversion result."""
        try:
            return self._read_register(ADS1015_REG_CONVERSION)
        except IOError as e:
            if self.debug:
                logging.error(f"Error reading last conversion: {e}")
            return None

    def start_continuous_conversion(self, channel=0, pga=6144, sps=250):
        """Start continuous conversion mode on the specified channel."""
        try:
            # Build the configuration register value
            config = 0x1000 | (channel << 12) | (self._swap_endian(pga) << 9) | sps
            self._write_register(ADS1015_REG_CONFIG, config)
            logging.info("ADS1015 started continuous conversion.")
        except IOError as e:
            if self.debug:
                logging.error(f"ADS1015 continuous start error: {e}")
            raise

    def start_single_ended_comparator(self, channel=0, threshold_high=2047, threshold_low=0, pga=6144, sps=250,
                                     active_low=True, traditional_mode=True, latching=False, num_readings=1):
        """
        Start a single-ended comparator with hysteresis.

        This method configures the ADS1015 to trigger an interrupt when the input voltage crosses a specified threshold.
        Hysteresis prevents spurious triggers when the signal bounces around the threshold.

        Args:
            channel (int): The ADC channel to monitor (0-3).
            threshold_high (int): The high threshold value.
            threshold_low (int): The low threshold value.
            pga (int): The programmable gain amplifier value in mV.
            sps (int): The samples per second.
            active_low (bool):  If True, the comparator is active low.
            traditional_mode (bool): If True, use traditional comparator mode.
            latching (bool): If True, enable latching comparator mode.
            num_readings (int): Number of readings to take before triggering.
        """
        if not 0 <= channel <= 3:
            raise ValueError("Channel must be between 0 and 3")

        config = 0x0000  # Start single conversion
        config |= (channel << 12)  # Channel selection
        config |= (self._swap_endian(threshold_high) << 9)  # High threshold
        config |= (self._swap_endian(threshold_low) << 5)  # Low threshold
        config |= (self._swap_endian(pga) << 2)  # PGA
        config |= sps
        config |= (0x01 if not active_low else 0x00)  # Active low or open drain
        config |= (0x01 if traditional_mode else 0x00)  # Traditional or latching
        config |= (1 if latching else 0)  # Latching or non-latching
        config |= (num_readings & 0x07)  # Number of readings (3 bits)

        try:
            self._write_register(ADS1015_REG_CONFIG, config)
            logging.info(f"ADS1015 comparator started on channel {channel} with hysteresis.")
        except IOError as e:
            if self.debug:
                logging.error(f"ADS1015 comparator start error: {e}")
            raise

