# Raspberry Pi QR code scanner for a kids coding lesson
# Uses picamera2 to capture a frame and pyzbar to decode a QR code
import time
import logging
from picamera2 import Picamera2
from pyzbar.pyzbar import decode

# Configure logging for the classroom demo
logging.basicConfig(level=logging.INFO, format="%(asctime)s - %(message)s")

def initialize_camera():
    """Initialize the CSI camera module using picamera2."""
    try:
        camera = Picamera2()
        config = camera.create_preview_configuration(main={"format": 'XRGB8888', "size": (640, 480)})
        camera.configure(config)
        camera.start()
        logging.info("CSI camera initialized successfully.")
        return camera
    except Exception as e:
        logging.error(f"Camera initialization failed: {e}")
        return None

def capture_frame(camera):
    """Capture a single frame from the CSI camera."""
    try:
        return camera.capture_array()
    except Exception as e:
        logging.error(f"Frame capture failed: {e}")
        return None

def decode_qr_code(frame):
    """Decode QR codes from a grayscale frame using pyzbar."""
    try:
        decoded_objects = decode(frame)
        if decoded_objects:
            return decoded_objects[0].data.decode("utf-8")
        return None
    except Exception as e:
        logging.error(f"QR code decoding failed: {e}")
        return None

def main():
    """Main function to run the QR code scanner."""
    camera = initialize_camera()
    if not camera:
        return

    try:
        # Capture a frame and decode for QR codes
        frame = capture_frame(camera)
        if frame is None:
            return

        qr_code_data = decode_qr_code(frame)
        if qr_code_data:
            print(f"QR code detected: {qr_code_data}")
        else:
            print("No QR code detected.")

    except Exception as e:
        logging.error(f"An unexpected error occurred: {e}")

    finally:
        # Always release the camera resource
        if camera:
            camera.stop()
            logging.info("CSI camera released.")

if __name__ == "__main__":
    main()

