#!/usr/bin/env python3

import gpiozero
import time
import logging
import signal
import sys
import json
import os

# Constants
CONFIG_FILE = "config.json"
DEFAULT_CONFIG = {
    "sensor_1": {"trigger_pin": 17, "echo_pin": 18, "offset": 0.0, "max_distance": 200.0},
    "sensor_2": {"trigger_pin": 22, "echo_pin": 23, "offset": 0.0, "max_distance": 200.0},
    "sensor_3": {"trigger_pin": 24, "echo_pin": 25, "offset": 0.0, "max_distance": 200.0},
    "alert_threshold_low": 10.0,
    "alert_threshold_high": 180.0,
    "alert_repeat_delay": 60,
    "log_file": "water_level.log"
}

# Global variables
running = True
sensor_data = {1: None, 2: None, 3: None}
alert_flags = {1: False, 2: False, 3: False}
last_alert_times = {1: 0, 2: 0, 3: 0}

# Custom exception classes
class SensorTimeoutError(Exception):
    pass

class InvalidSensorError(Exception):
    pass

class ConfigurationError(Exception):
    pass

# Configuration management functions
def load_config():
    """Loads configuration from config.json, creating defaults if necessary."""
    try:
        with open(CONFIG_FILE, "r") as f:
            config = json.load(f)
        # Merge loaded config with defaults, prioritizing loaded values
        config = {**DEFAULT_CONFIG, **config}
        return config
    except FileNotFoundError:
        logging.warning("Config file not found, creating default configuration.")
        return DEFAULT_CONFIG
    except json.JSONDecodeError:
        logging.error("Error decoding config file, using default configuration.")
        return DEFAULT_CONFIG

def save_config(config):
    """Saves the current configuration to config.json."""
    try:
        with open(CONFIG_FILE, "w") as f:
            json.dump(config, f, indent=4)
    except IOError as e:
        logging.error(f"Error saving config to file: {e}")

# Modular subsystem functions
def measure_distance(trigger_pin, echo_pin, offset, max_distance):
    """Measures the distance using an HC-SR04 ultrasonic sensor."""
    try:
        # Initialize the sensor
        sensor = gpiozero.DistanceSensor(echo=echo_pin, trigger=trigger_pin, max_distance=max_distance)
        # Take 3 readings to get a more accurate average
        readings = []
        for _ in range(3):
            distance = sensor.distance * (1 + offset / 100)  # Apply calibration offset
            readings.append(distance)
            time.sleep(0.1)  # Small delay between readings
        if not readings:
            raise SensorTimeoutError("No readings received from sensor.")
        distance = sum(readings) / len(readings)  # Calculate average
        sensor.close() # Release the sensor
        return distance
    except gpiozero.exc.GPIODeviceError as e:
        logging.error(f"GPIO error during measurement: {e}")
        raise
    except Exception as e:
        logging.error(f"Error measuring distance: {e}")
        raise

def calculate_water_level(distance, max_distance):
    """Calculates the water level based on the measured distance."""
    if distance is None:
        return None
    water_level = max_distance - distance
    return water_level

def check_alerts(sensor_id, water_level, alert_threshold_low, alert_threshold_high, alert_repeat_delay):
    """Checks if the water level exceeds the alert thresholds and logs alerts."""
    global alert_flags, last_alert_times
    if water_level is None:
        return

    if water_level < alert_threshold_low:
        if not alert_flags[sensor_id]:
            logging.warning(f"Sensor {sensor_id}: Water level low ({water_level:.2f}mm), threshold low ({alert_threshold_low:.2f}mm)")
            alert_flags[sensor_id] = True
            last_alert_times[sensor_id] = time.time()
    elif water_level > alert_threshold_high:
        if not alert_flags[sensor_id]:
            logging.warning(f"Sensor {sensor_id}: Water level high ({water_level:.2f}mm), threshold high ({alert_threshold_high:.2f}mm)")
            alert_flags[sensor_id] = True
            last_alert_times[sensor_id] = time.time()
    else:
        if alert_flags[sensor_id]:
            logging.info(f"Sensor {sensor_id}: Water level back to normal ({water_level:.2f}mm)")
            alert_flags[sensor_id] = False
            last_alert_times[sensor_id] = time.time()

# Resource management functions
def setup_gpio():
    """Initializes the GPIO pins for the ultrasonic sensors."""
    try:
        # Initialize the distance sensor objects
        sensor1 = gpiozero.DistanceSensor(echo=DEFAULT_CONFIG["sensor_1"]["echo_pin"], trigger=DEFAULT_CONFIG["sensor_1"]["trigger_pin"], max_distance=DEFAULT_CONFIG["sensor_1"]["max_distance"])
        sensor2 = gpiozero.DistanceSensor(echo=DEFAULT_CONFIG["sensor_2"]["echo_pin"], trigger=DEFAULT_CONFIG["sensor_2"]["trigger_pin"], max_distance=DEFAULT_CONFIG["sensor_2"]["max_distance"])
        sensor3 = gpiozero.DistanceSensor(echo=DEFAULT_CONFIG["sensor_3"]["echo_pin"], trigger=DEFAULT_CONFIG["sensor_3"]["trigger_pin"], max_distance=DEFAULT_CONFIG["sensor_3"]["max_distance"])
        return sensor1, sensor2, sensor3
    except gpiozero.exc.GPIODeviceError as e:
        logging.error(f"GPIO initialization error: {e}")
        sys.exit(1)

def cleanup_gpio(sensor1, sensor2, sensor3):
    """Releases the GPIO resources."""
    try:
        sensor1.close()
        sensor2.close()
        sensor3.close()
        logging.info("GPIO resources released.")
    except Exception as e:
        logging.error(f"Error releasing GPIO resources: {e}")

# Signal handlers
def signal_handler(sig, frame):
    """Handles signals for graceful shutdown."""
    global running
    logging.info("Received signal, shutting down...")
    running = False

# Logging configuration and utilities
def configure_logging(log_file):
    """Configures the logging module."""
    logging.basicConfig(filename=log_file, level=logging.INFO,
                        format='%(asctime)s - %(levelname)s - %(message)s')
    # Add a stream handler to also log to the console
    stream_handler = logging.StreamHandler(sys.stdout)
    stream_handler.setLevel(logging.INFO)
    formatter = logging.Formatter('%(asctime)s - %(levelname)s - %(message)s')
    stream_handler.setFormatter(formatter)
    logging.getLogger().addHandler(stream_handler)

