#!/usr/bin/env python3

import speech_recognition as sr
import RPi.GPIO as GPIO
import picamera2
import time
import datetime
import os
import signal
import sys
import random

# Constants and configuration
DHT_PIN = 4  # GPIO pin for DHT11 sensor (BCM numbering)
LIGHT_PIN = 17  # GPIO pin for the simulated light
WAKE_WORD = "Greenhouse"
COMMANDS = ["turn on the lights", "turn off the lights", "what is the temperature", "take a picture"]
TEMP_MIN = 15
TEMP_MAX = 35

# Global variables
camera = None
microphone = None

# Custom exception classes
class SensorError(Exception):
    pass

class CameraError(Exception):
    pass

class GPIOError(Exception):
    pass

# Configuration management functions
def load_configuration():
    """Loads configuration from a file (simulated)."""
    # In a real application, this would read from a file.
    # For this example, we simulate loading the configuration.
    return {}

# Modular subsystem functions
def initialize_gpio():
    """Initializes the GPIO pins."""
    try:
        GPIO.setmode(GPIO.BCM)
        GPIO.setup(LIGHT_PIN, GPIO.OUT)
        GPIO.output(LIGHT_PIN, GPIO.LOW)  # Ensure lights are off initially
        return True
    except Exception as e:
        print(f"Error initializing GPIO: {e}")
        return False

def turn_lights_on():
    """Turns the simulated light on."""
    try:
        GPIO.output(LIGHT_PIN, GPIO.HIGH)
        print("Lights turned on")
    except Exception as e:
        print(f"Error turning lights on: {e}")

def turn_lights_off():
    """Turns the simulated light off."""
    try:
        GPIO.output(LIGHT_PIN, GPIO.LOW)
        print("Lights turned off")
    except Exception as e:
        print(f"Error turning lights off: {e}")

def read_temperature():
    """Reads the temperature from the DHT11 sensor."""
    try:
        # Simulate DHT11 reading
        temperature = random.uniform(TEMP_MIN, TEMP_MAX)
        return temperature
    except Exception as e:
        print(f"Error reading temperature: {e}")
        return None

def capture_image():
    """Captures an image using the Raspberry Pi camera."""
    try:
        timestamp = datetime.datetime.now().strftime("%Y%m%d_%H%M%S")
        filename = f"greenhouse_{timestamp}.jpg"
        camera.capture_file(filename)
        print(f"Image captured: {filename}")
    except Exception as e:
        print(f"Error capturing image: {e}")

def process_command(command):
    """Processes the recognized voice command."""
    if command == "turn on the lights":
        turn_lights_on()
    elif command == "turn off the lights":
        turn_lights_off()
    elif command == "what is the temperature":
        temperature = read_temperature()
        if temperature is not None:
            print(f"The temperature is {temperature:.2f}°C")
        else:
            print("Could not read temperature.")
    elif command == "take a picture":
        capture_image()
    else:
        print("Unknown command.")

# Resource management functions
def setup_resources():
    """Sets up the necessary resources (GPIO, camera)."""
    global camera, microphone
    try:
        # Initialize camera
        camera = picamera2.Picamera2()
        camera.configure(camera.create_preview_configuration(main={"format": 'XRGB8888', "size": (640, 480)}))
        camera.start()
        print("Camera initialized successfully.")
    except Exception as e:
        print(f"Error initializing camera: {e}")
        camera = None  # Set camera to None to indicate failure

    try:
        # Initialize microphone
        microphone = sr.Microphone()
        print("Microphone initialized successfully.")
    except Exception as e:
        print(f"Error initializing microphone: {e}")
        microphone = None  # Set microphone to None to indicate failure

def cleanup_resources():
    """Cleans up the resources (GPIO, camera)."""
    print("Cleaning up resources...")
    if camera:
        try:
            camera.close()
            print("Camera closed.")
        except Exception as e:
            print(f"Error closing camera: {e}")
    if microphone:
        try:
            microphone.close()
            print("Microphone closed.")
