import serial
import time

# RS485 temperature sensor configuration for Raspberry Pi
SERIAL_PORT = '/dev/ttyUSB0'
BAUD_RATE = 115200
TIMEOUT = 1

def read_temperature(serial_connection):
    """Read and parse a temperature value from the RS485 sensor."""
    try:
        line = serial_connection.readline().decode('ascii', errors='replace').strip()
        if line:
            try:
                temperature_value = float(line)
                return temperature_value
            except ValueError:
                print("Invalid temperature data received:", line)
                return None
        return None
    except Exception as read_error:
        print("Error reading sensor:", read_error)
        return None

def main():
    """Continuously read and display temperature data."""
    serial_connection = None
    try:
        # Open the serial port for the RS485 sensor
        serial_connection = serial.Serial(SERIAL_PORT, BAUD_RATE, timeout=TIMEOUT)
        while True:
            temperature_value = read_temperature(serial_connection)
            if temperature_value is not None:
                print('Temperature: {:.1f} C'.format(temperature_value))
            time.sleep(0.5)
    except serial.SerialException as serial_error:
        print('Serial port error:', serial_error)
    except KeyboardInterrupt:
        print('\nExiting temperature monitoring...')
    finally:
        # Close the serial connection
        if serial_connection is not None:
            serial_connection.close()

if __name__ == '__main__':
    main()

