    "gpio_transmitter_pin": 17,
    "gpio_dht22_pin": 4,
    "dht22_read_interval": 60,
    "log_file": "greenhouse.log",
    "outlet_configurations": [
        {"unit_code": "1", "system_code": "10101", "state": "on"},
        {"unit_code": "2", "system_code": "10101", "state": "off"},
        {"unit_code": "3", "system_code": "10101", "state": "on"}
    ]
}

# Configure logging
logging.basicConfig(
    level=logging.INFO,
    format="%(asctime)s [%(levelname)s] %(message)s",
    handlers=[
        logging.FileHandler("greenhouse.log", maxBytes=1024*1024, backupCount=5),
        logging.StreamHandler()
    ]
)

# Global variable to track outlet state changes
outlet_states = {}

def load_config(config_file):
    """Loads configuration from a JSON file, using defaults if the file is missing or invalid."""
    try:
        with open(config_file, "r") as f:
            config = json.load(f)
        # Validate the configuration
        if not all(key in config for key in DEFAULT_CONFIG):
            logging.warning("Missing keys in config file. Using default values.")
            config = DEFAULT_CONFIG
        return config
    except (FileNotFoundError, json.JSONDecodeError):
        logging.warning("Config file not found or invalid. Using default configuration.")
        return DEFAULT_CONFIG

def setup_gpio(transmitter_pin, dht22_pin):
    """Sets up GPIO pins for the transmitter and DHT22 sensor."""
    GPIO.setmode(GPIO.BCM)
    GPIO.setup(transmitter_pin, GPIO.OUT)
    GPIO.setup(dht22_pin, GPIO.IN, pull_up_down=GPIO.PUD_UP)
    global transmitter_pin, dht22_pin
    return transmitter_pin, dht22_pin

def setup_dht22(dht22_pin):
    """Initializes the DHT22 sensor."""
    try:
        dht_device = adafruit_dht.DHT22(digitalio.DigitalInOut(dht22_pin))
        return dht_device
    except RuntimeError as e:
        logging.error(f"Failed to initialize DHT22 sensor: {e}")
        return None

def read_dht22(dht_device):
    """Reads temperature and humidity from the DHT22 sensor."""
    try:
        temperature = dht_device.temperature
        humidity = dht_device.humidity
        if temperature is not None and humidity is not None:
            return temperature, humidity
        else:
            logging.warning("DHT22 sensor returned None values.")
            return None, None
    except RuntimeError as e:
        logging.error(f"DHT22 sensor error: {e}")
        return None, None
    except OSError as e:
        logging.error(f"DHT22 sensor bus error: {e}")
        return None, None

def transmit_code(transmitter_pin, system_code, unit_code, state, retry_count=3):
    """Transmits a 433MHz signal to control an outlet."""
    for attempt in range(retry_count):
        try:
            # Encode the data
            data = f"10101{unit_code}{state}"  # Example encoding
            # Send the signal (replace with actual PT2262 initialization and send)
            # This is a placeholder for the actual transmitter control logic
