            time.sleep(0.05)  # Short delay
            return  # Success, exit the function
        except Exception as e:
            logging.error(f"Transmission failed (attempt {attempt+1}): {e}")
            time.sleep(0.1)  # Wait before retrying
    logging.error(f"Failed to transmit code after {retry_count} attempts.")
    return None

async def control_outlet(outlet_name, state, transmitter_pin, dht22_pin, outlet_configurations):
    """Controls an outlet based on the given state."""
    unit_code = next((config["unit_code"] for config in outlet_configurations if config["unit_code"] == outlet_name), None)
    if unit_code is None:
