        return

    system_code = "10101"
    if state == "on":
        state_bit = 1
    elif state == "off":
        state_bit = 0
    else:
        logging.warning(f"Invalid state: {state}")
        return

    if unit_code and system_code in [config["system_code"] for config in outlet_configurations]:
        code = transmit_code(transmitter_pin, system_code, unit_code, state_bit)
        if code:
            outlet_states[outlet_name] = state
            logging.info(f"Outlet {outlet_name} turned {state}")
        else:
            logging.warning(f"Failed to control outlet {outlet_name}. Retrying...")
    else:
        logging.warning(f"Outlet {outlet_name} not configured.")

async def sensor_reading_task(transmitter_pin, dht22_pin, dht22_device, dht22_read_interval, outlet_configurations):
    """Reads sensor data and controls outlets based on the readings."""
    while True:
        temperature, humidity = read_dht22(dht22_device)
        if temperature is not None and humidity is not None:
            logging.info(f"Temperature: {temperature:.2f}°C, Humidity: {humidity:.2f}%")
