                elif config["unit_code"] == "3":
                    if temperature > 28 and humidity < 75:
                        control_outlet("3", "on")
                    else:
                        control_outlet("3", "off")
        else:
            logging.warning("Failed to read sensor data. Retrying...")
        await asyncio.sleep(dht22_read_interval)

async def cli_task(transmitter_pin, dht22_pin, dht22_device, dht22_read_interval, outlet_configurations):
    """Handles command-line interface commands."""
    while True:
        command = input("Enter command (on, off, status, exit): ").lower()
        if command == "on":
            await control_outlet("1", "on")
        elif command == "off":
            await control_outlet("1", "off")
        elif command == "status":
            for config in outlet_configurations:
                print(f"Outlet {config['unit_code']} is {'ON' if outlet_states.get(config['unit_code']) else 'OFF'}")
        elif command == "exit":
            break
        else:
            print("Invalid command.")

async def main():
    """Main function to run the greenhouse controller."""
    try:
        # Load configuration
        config = load_config(CONFIG_FILE)
        dht22_read_interval = config["dht22_read_interval"]
        transmitter_pin = config["gpio_transmitter_pin"]
        dht22_pin = config["gpio_dht22_pin"]
        log_file = config["log_file"]

        # Setup GPIO
        transmitter_pin, dht22_pin = setup_gpio(transmitter_pin, dht22_pin)

        # Setup DHT22 sensor
        dht22_device = setup_dht22(dht22_pin)

        # Start tasks
        await asyncio.gather(
            sensor_reading_task(transmitter_pin, dht22_pin, dht22_device, dht22_read_interval, outlet_configurations),
            cli_task(transmitter_pin, dht22_pin, dht22_device, dht22_read_interval, outlet_configurations)
        )

    except Exception as e:
        logging.error(f"An error occurred: {e}")
    finally:
        # Cleanup GPIO on exit
        GPIO.cleanup()
        logging.info("Greenhouse controller stopped.")

if __name__ == "__main__":
    try:
        asyncio.run(main())
    except KeyboardInterrupt:
        print("Exiting...")
    finally:
        GPIO.cleanup()
        logging.info("Program terminated.")

