import time

# Raspberry Pi CPU temperature monitor for a kids coding lesson
# Reads the CPU temperature every 5 seconds and prints it

def read_cpu_temp():
    """Read the CPU temperature from the Raspberry Pi thermal zone file."""
    # gpiozero.CPUTemperature reads the /sys/class/thermal/thermal_zone0/temp file
    try:
        cpu_temp = CPUTemperature().temperature
        return round(cpu_temp, 2)
    except FileNotFoundError:
        # The thermal zone file might not exist on some systems
        return None
    except Exception as read_error:
        print(f"Error reading temperature: {read_error}")
        return None

if __name__ == "__main__":
    # Main loop to continuously read and print the CPU temperature
    try:
        while True:
            cpu_temp_value = read_cpu_temp()
            if cpu_temp_value is not None:
                print("CPU Temperature: {:.2f} °C".format(cpu_temp_value))
            time.sleep(5)
    except KeyboardInterrupt:
        print("Program terminated")
    except Exception as loop_error:
        print(f"An error occurred: {loop_error}")
    finally:
        # No GPIO pins are used in this script, so nothing to clean up
        pass

