import time
import board
import busio
import adafruit_tca9548a
import adafruit_bme280
import adafruit_tsl2591

# Configuration constants
I2C_BUS_NUMBER = 1
BME280_ADDRESS = 0x76  # Default address
TSL2591_ADDRESS = 0x29  # Default address
TCA9548A_ADDRESS = 0x70
READ_INTERVAL_SECONDS = 2

def initialize_i2c_bus():
    """Initialize the I2C bus."""
    try:
        return busio.I2C(board.SCL, board.SDA)
    except Exception as e:
        print(f"Error initializing I2C bus: {e}")
        return None

def initialize_multiplexer(i2c_bus):
    """Initialize the TCA9548A I2C multiplexer."""
    try:
        return adafruit_tca9548a.TCA9548A(i2c_bus, address=TCA9548A_ADDRESS)
    except Exception as e:
        print(f"Error initializing multiplexer: {e}")
        return None

def initialize_bme280(multiplexer, address=BME280_ADDRESS):
    """Initialize the BME280 sensor."""
    try:
        sensor = multiplexer.get_sensor(adafruit_bme280.Adafruit_BME280_I2C)
        sensor.sea_level_pressure = 1013.25  # Standard sea level pressure
        return sensor
    except Exception as e:
        print(f"Error initializing BME280: {e}")
        return None

def initialize_tsl2591(multiplexer, address=TSL2591_ADDRESS):
    """Initialize the TSL2591 sensor."""
    try:
        sensor = multiplexer.get_sensor(adafruit_tsl2591.TSL2591)
        return sensor
    except Exception as e:
        print(f"Error initializing TSL2591: {e}")
        return None

def read_bme280_data(sensor):
    """Read temperature, humidity, and pressure from the BME280 sensor."""
    try:
        temperature = sensor.temperature
        humidity = sensor.humidity
        pressure = sensor.pressure
        return temperature, humidity, pressure
    except Exception as e:
        print(f"Error reading BME280 data: {e}")
        return None, None, None

def read_tsl2591_data(sensor):
    """Read light intensity from the TSL2591 sensor."""
    try:
        light_intensity = sensor.lux
        return light_intensity
    except Exception as e:
        print(f"Error reading TSL2591 data: {e}")
        return None

def display_sensor_data(temperature, humidity, pressure, light_intensity):
    """Print the sensor readings to the console."""
    print(f"Temperature: {temperature:.2f} C")
    print(f"Humidity: {humidity:.2f} %")
    print(f"Pressure: {pressure:.2f} hPa")
    print(f"Light Intensity: {light_intensity:.2f} lux")

def main():
    """Main function to read and display sensor data."""
    i2c_bus = initialize_i2c_bus()
    if i2c_bus is None:
        return

    multiplexer = initialize_multiplexer(i2c_bus)
    if multiplexer is None:
        return

    bme280_sensor = initialize_bme280(multiplexer)
    if bme280_sensor is None:
        return

    tsl2591_sensor = initialize_tsl2591(multiplexer)
    if tsl2591_sensor is None:
        return

    try:
        while True:
            temperature, humidity, pressure = read_bme280_data(bme280_sensor)
            light_intensity = read_tsl2591_data(tsl2591_sensor)

            if all(v is not None for v in [temperature, humidity, pressure, light_intensity]):
                display_sensor_data(temperature, humidity, pressure, light_intensity)

            time.sleep(READ_INTERVAL_SECONDS)

    except KeyboardInterrupt:
        print("Exiting program.")
    except Exception as e:
        print(f"An unexpected error occurred: {e}")
    finally:
        # No specific cleanup needed for these libraries, but good practice to include a finally block
        pass

if __name__ == "__main__":
    main()

