import busio
import adafruit_ahtx0

# I2C address of the AHT20 sensor
AHT20_ADDRESS = 0x38
# I2C bus number on the Raspberry Pi
I2C_BUS_NUMBER = 1
# Retry delay in seconds
RETRY_DELAY = 5


def initialize_i2c():
    """Initialize the I2C bus."""
    try:
        return busio.I2C(board.SCL, board.SDA)
    except Exception as e:
        print(f"Error initializing I2C: {e}")
        return None


def initialize_sensor(i2c_bus):
    """Initialize the AHT20 sensor."""
    try:
        return adafruit_ahtx0.AHTx0(i2c_bus)
    except Exception as e:
        print(f"Error initializing AHT20 sensor: {e}")
        return None


def read_sensor_data(sensor_device):
    """Read temperature and humidity from the sensor."""
    try:
        sensor_device.measure()
        temperature_celsius = sensor_device.temperature
        humidity_percent = sensor_device.relative_humidity
        return temperature_celsius, humidity_percent
    except Exception as e:
        print(f"Error reading sensor data: {e}")
        return None, None


def validate_sensor_readings(temperature, humidity):
    """Validate that temperature and humidity readings are valid."""
    if temperature is None or humidity is None:
        return False
    if not -40 <= temperature <= 85:
        print(f"Invalid temperature reading: {temperature}°C")
        return False
    if not 0 <= humidity <= 100:
        print(f"Invalid humidity reading: {humidity}%")
        return False
    return True


def main():
    """Main function to read and display temperature and humidity."""
    i2c_bus = initialize_i2c()
    if i2c_bus is None:
        return

    sensor = initialize_sensor(i2c_bus)
    if sensor is None:
        return

    try:
        while True:
            temperature, humidity = read_sensor_data(sensor)

            if validate_sensor_readings(temperature, humidity):
                print(f"{time.strftime('%Y-%m-%d %H:%M:%S')}, Temperature: {temperature:.1f} C Humidity: {humidity:.1f} %")

            time.sleep(RETRY_DELAY)

    except KeyboardInterrupt:
        print("Shutting down...")
    finally:
        i2c_bus.deinit()


if __name__ == "__main__":
    main()

