from gpiozero import PWMOutputDevice
import time
import subprocess
import signal
import sys

# Cooling fan control for a Raspberry Pi using PWM
FAN_PIN = 14
PWM_FREQUENCY = 100
DEFAULT_DUTY_CYCLE = 100
TEMPERATURE_CHECK_INTERVAL = 5

class CoolingFan:
    """Controls a cooling fan based on CPU temperature."""

    def __init__(self, pin, frequency):
        """Set up the fan pin and PWM frequency."""
        self.fan = PWMOutputDevice(pin, frequency=frequency)
        self.fan.value = DEFAULT_DUTY_CYCLE
        self.previous_temp = None

    def get_temp(self):
        """Read the CPU temperature via vcgencmd."""
        try:
            output = subprocess.check_output(["vcgencmd", "measure_temp"]).decode("utf-8")
            temp_str = output.split("=")[1].split("'")[0]
            return float(temp_str)
        except (subprocess.CalledProcessError, IndexError, ValueError):
            return None

    def set_speed(self, duty_cycle):
        """Set the fan speed in duty cycle."""
        self.fan.value = duty_cycle

    def run(self):
        """Continuously monitor temperature and adjust fan speed."""
        signal.signal(signal.SIGINT, self.stop)
        signal.signal(signal.SIGTERM, self.stop)
        while True:
            current_temp = self.get_temp()
            if current_temp is not None:
                if current_temp > 70:
                    self.set_speed(100)
                elif current_temp > 60:
                    self.set_speed(85)
                elif current_temp > 50:
                    self.set_speed(70)
                elif current_temp > 40:
                    self.set_speed(50)
                elif current_temp > 32:
                    self.set_speed(25)
                elif current_temp > 25:
                    self.set_speed(15)
                else:
                    self.set_speed(DEFAULT_DUTY_CYCLE)
            time.sleep(TEMPERATURE_CHECK_INTERVAL)

    def stop(self, signum=None):
        """Stop the fan and release resources."""
        print("Stopping cooling fan")
        self.fan.value = DEFAULT_DUTY_CYCLE  # Set to default on exit
        self.fan.close()
        sys.exit(0)

if __name__ == "__main__":
    fan = CoolingFan(FAN_PIN, PWM_FREQUENCY)
    fan.run()

