#!/usr/bin/env python3

# MCP23017 I2C GPIO expander demo for Raspberry Pi (Beginner level)
# Demonstrates basic output and input on a 74HC595 shift register controlled via an MCP23017.
# Uses smbus2 for I2C communication.

import smbus2
import time
import logging

# Logging setup
logging.basicConfig(level=logging.INFO, format='%(asctime)s - %(levelname)s - %(message)s')
logger = logging.getLogger(__name__)

# MCP23017 I2C address and register map
MCP23017_ADDRESS = 0x20
# Output register addresses
OUTPUT_REGISTER_A = 0x00
OUTPUT_REGISTER_B = 0x01
# Input register address
INPUT_REGISTER = 0x0C
# Control register addresses
MODE_REGISTER = 0x04
SHUTDOWN_REGISTER = 0x05
# Register addresses for the 74HC595 shift register
DATA_REGISTER_A = 0x12
DATA_REGISTER_B = 0x13
OLATA = 0x14
OLATB = 0x15

class MCP23017:
    """Driver for the MCP23017 I2C GPIO expander."""

    def __init__(self, address=MCP23017_ADDRESS, busnum=0):
        """Initializes the MCP23017 driver."""
        try:
            self.bus = smbus2.SMBus(busnum)
        except FileNotFoundError:
            logger.error("I2C bus not found. Check your Raspberry Pi configuration.")
            raise
        self.address = address
        self.chipid = self._read_chipid()
        if self.chipid != 0x20:
            logger.error(f"MCP23017 not detected at address 0x{self.address:02X}. Chip ID: 0x{self.chipid:02X}")
            raise

    def _read_chipid(self):
        """Read the chip ID register."""
        return self.bus.read_byte_data(self.address, 0x00)

    def _write_chipid(self, chipid):
        """Write the chip ID register."""
        self.bus.write_byte_data(self.address, 0x00, chipid)

    def write_register(self, register, value):
        """Writes a byte to a specific register."""
        try:
            self.bus.write_byte_data(self.address, register, value)
        except OSError as e:
            logger.error(f"I2C write error: {e}")
            raise

    def read_register(self, register):
        """Reads a byte from a specific register."""
        try:
            return self.bus.read_byte_data(self.address, register)
        except OSError as e:
            logger.error(f"I2C read error: {e}")
            raise

    def write_output_a(self, bit, value):
        """Writes a value to output A (shift register data)."""
        if not 0x80 & bit:
            value |= 0x01
        else:
            value &= ~0x01
        self.write_register(OUTPUT_REGISTER_A, value)

    def write_output_b(self, bit, value):
        """Writes a value to output B (shift register data)."""
        if not 0x80 & bit:
            value |= 0x01
        else:
            value &= ~0x01
        self.write_register(OUTPUT_REGISTER_B, value)

    def read_input_a(self, bit):
        """Reads the state of input A (shift register data)."""
        return self.read_register(INPUT_REGISTER) & (1 << bit)

    def read_input_b(self, bit):
        """Reads the state of input B (shift register data)."""
        return self.read_register(INPUT_REGISTER) & (1 << bit)

    def set_mode(self, mode):
        """Sets the MCP23017 operating mode."""
        self.write_register(MODE_REGISTER, mode)

    def shutdown(self):
        """Shuts down the MCP23017."""
        self.write_register(SHUTDOWN_REGISTER, 0x01)

    def cleanup(self):
        """Releases the I2C bus."""
        try:
            self.bus.close()
        except AttributeError:  # bus might not be initialized
            pass


def setup_gpio(mcp23017):
    """Configures the MCP23017 for output on GPA0 and input with pull-up on GPB7."""
    try:
        mcp23017.write_output_a(0, 0x00)  # GPA0 as output, all low
        mcp23017.write_output_b(7, 0x01)  # GPB7 with internal pull-up, high
        mcp23017.set_mode(0x00)  # Normal mode
    except Exception as e:
        logger.error(f"GPIO setup failed: {e}")
        raise


def main():
    """Main program loop."""
    try:
        mcp23017 = MCP23017()
        if mcp23017.chipid != 0x20:
            raise Exception("MCP23017 not found")

        setup_gpio(mcp23017)
        mcp23017.shutdown()

        while True:
            switch_state = mcp23017.read_input_b(7)
            if switch_state == 0:
                mcp23017.write_output_a(0, 0x01)  # Toggle LED
                logger.info("Switch pressed, LED toggled")
            else:
                mcp23017.write_output_a(0, 0x00)  # LED off
                logger.info("Switch released, LED off")
            time.sleep(0.1)

    except KeyboardInterrupt:
        logger.info("Exiting program")
    except Exception as e:
        logger.exception(f"An unexpected error occurred: {e}")
    finally:
        mcp23017.shutdown()
        mcp23017.cleanup()


if __name__ == "__main__":
    main()

