import sys
import threading
import RPi.GPIO as GPIO
import signal
import time

# Configuration
LOG_FILE = "dog.log"
POLL_INTERVAL = 0.1  # seconds

# GPIO setup
GPIO.setmode(GPIO.BCM)

# Global variables
server_running = True
log_file_path = None

# Signal handler for graceful exit
def signal_handler(sig, frame):
    global server_running, log_file_path
    print("\nExiting gracefully...")
    server_running = False
    if log_file_path:
        try:
            log_file_path.close()
        except Exception as e:
            print(f"Error closing log file: {e}")
    GPIO.cleanup()
    sys.exit(0)

# Register signal handler
signal.signal(signal.SIGINT, signal_handler)
signal.signal(signal.SIGTERM, signal_handler)

# Data transfer functions
def send_data(data_string):
    """Sends data to the server."""
    try:
        if log_file_path:
            log_file_path.write(data_string + "\n")
            log_file_path.flush()  # Ensure data is written immediately
        else:
            print(f"Data sent: {data_string}")
    except Exception as e:
        print(f"Error sending data: {e}")

def receive_data():
    """Receives data from the server."""
    global server_running, log_file_path
    while server_running:
        try:
            data_string = DOG.receive()
            if data_string:
                if log_file_path:
                    try:
                        log_file_path.write(data_string + "\n")
                        log_file_path.flush()
                    except Exception as e:
                        print(f"Error writing to log file: {e}")
                else:
                    print(f"Received: {data_string}")
        except Exception as e:
            print(f"Error receiving data: {e}")
        time.sleep(POLL_INTERVAL)

# Server thread
def server_thread_function():
    """Manages the server and receive thread."""
    global server_running, log_file_path
    try:
        DOG.start()
        receive_thread = threading.Thread(target=receive_data)
        receive_thread.daemon = True  # Allow the main thread to exit even if this is running
        receive_thread.start()
        print("Server started.")
    except Exception as e:
        print(f"Error starting server: {e}")
        server_running = False  # Ensure cleanup on error

# Command dispatcher
def handle_command(command):
    """Handles user commands."""
    global server_running, log_file_path
    parts = command.split()
    if not parts:
        return

    command_name = parts[0].lower()

    if command_name == "start":
        if len(parts) == 2:
            log_file_path = open(parts[1], "a")
            threading.Thread(target=server_thread_function).start()
            print(f"Server started. Logging to {parts[1]}. Press Ctrl+C to stop.")
        else:
            print("Usage: start ")
    elif command_name == "stop":
        server_running = False
        if log_file_path:
            log_file_path.close()
            print("Server stopped.")
    elif command_name == "help":
        if len(parts) == 2:
            print(f"Help for {command_name}:")
            print(f"  {command_name} <filename>")
            print(f"  {command_name} help")
            print(f"  {command_name} start <filename>")
            print(f"  {command_name} stop")
            print(f"  {command_name} display")
            print(f"  {command_name} send <data>")
            print(f"  {command_name} write <data>")
    elif command_name == "display":
        if log_file_path:
            try:
                with open(log_file_path.name, "r") as f:
                    print(f.read())
            except Exception as e:
                print(f"Error reading log file: {e}")
    elif command_name == "send":
        if len(parts) == 2:
            send_data(parts[1])
    elif command_name == "write":
        if len(parts) == 2:
            send_data(parts[1])
    else:
        print("Invalid command.")

# Main server loop
def main():
    """Main server loop."""
    global server_running, log_file_path
    print("Starting DOG...")
    print("Type 'help' for a list of commands.")

    try:
        while server_running:
            command = input("> ")
            handle_command(command)
    except KeyboardInterrupt:
        print("\nKeyboard interrupt detected. Type 'stop' to exit.")
    finally:
        server_running = False
        if log_file_path:
            try:
                log_file_path.close()
            except Exception as e:
                print(f"Error closing log file: {e}")
        GPIO.cleanup()
        print("DOG stopped.")

if __name__ == "__main__":
    main()

