from gpiozero import DigitalInputDevice, Buzzer
import time

# Define the GPIO pin numbers for the tilt sensor and buzzer
TILT_SENSOR_PIN = 17
BUZZER_PIN = 27
POLL_INTERVAL_SECONDS = 0.1


def setup_tilt_sensor(pin):
    """Create and return a DigitalInputDevice configured for the tilt sensor."""
    return DigitalInputDevice(pin, pull_up=True)


def setup_buzzer(pin):
    """Create and return a Buzzer object."""
    return Buzzer(pin)


def sound_buzzer(buzzer, duration_seconds):
    """Sound the buzzer for the given duration in seconds."""
    buzzer.on()
    time.sleep(duration_seconds)
    buzzer.off()


def main():
    """Monitor the tilt sensor and sound the buzzer when tilted."""
    tilt_sensor = setup_tilt_sensor(TILT_SENSOR_PIN)
    buzzer = setup_buzzer(BUZZER_PIN)

    try:
        while True:
            # Read the tilt sensor value.  LOW means tilted
            tilt_detected = tilt_sensor.value == 0
            if tilt_detected:
                sound_buzzer(buzzer, 1)  # Buzz for 1 second
            else:
                buzzer.off()  # Ensure buzzer is off when not tilted
            time.sleep(POLL_INTERVAL_SECONDS)
    except KeyboardInterrupt:
        # Allow the user to stop the program with Ctrl+C
        print("Stopping tilt buzzer monitor")
    finally:
        # Release GPIO resources
        tilt_sensor.close()
        buzzer.close()


if __name__ == "__main__":
    main()

