#!/usr/bin/python3

"""
Control a Raspberry Pi GPIO pin as an output using the pigpio library.

This module provides a robust and optimized way to drive a GPIO pin,
incorporating error handling, performance optimizations, and best practices
for interacting with hardware on a Raspberry Pi.
"""

import pigpio
from enum import Enum
import time
import logging

# Configure logging
logging.basicConfig(level=logging.INFO, format='%(asctime)s - %(levelname)s - %(message)s')
logger = logging.getLogger(__name__)


class PinState(Enum):
    """
    An enumeration representing the possible states of a GPIO pin.
    """
    OFF = "off"
    ON = "on"


class OutputPin:
    """
    A class for controlling a GPIO pin as an output.
    """

    DEFAULT_PIN_NUMBER = 17
    """
    The default Broadcom BCM pin number to use if not specified.
    """

    def __init__(self, pin_number: int, initial_value: PinState,
                 connection_timeout: float = 5.0, retest_delay: float = 0.1,
                 pigpies: list = None):
        """
        Initializes and connects an output pin.

        Args:
            pin_number (int): The Broadcom BCM pin number.
            initial_value (PinState): The initial state of the pin (OFF or ON).
            connection_timeout (float): Timeout for establishing a connection to pigpio.
            retest_delay (float): Delay between connection attempts.
            pigpies (list): Optional list of pigpio connections to use.  If provided,
                           the pin will be controlled by all connections.

        Raises:
            TypeError: If pin_number is not an integer or initial_value is not a PinState.
            ValueError: If pin_number is invalid (out of range).
            ConnectionError: If a connection to pigpio cannot be established.
        """

        if not isinstance(pin_number, int):
            raise TypeError("pin_number must be an integer.")
        if not isinstance(initial_value, PinState):
            raise TypeError("initial_value must be a PinState.")

        if not (0 <= pin_number <= pigpio.get_i2c_max_device() - 1):
            raise ValueError(f"Pin number {pin_number} is out of range (0-{pigpio.get_i2c_max_device()-1}).")

        self.pin_number = pin_number
        self.initial_value = initial_value
        self.pigpies = pigpies if pigpies is not None else [pigpio.pi()]  # Default to a single connection if not provided
        self.pigpio_connections_info = {} # Store connection info for each pigpio connection

        if self.pigpies:
            logger.info(f"Using pigpio connections: {self.pigpies}")
        else:
            try:
                self.pi = pigpio.pi()
            else:
                raise ConnectionError("Failed to connect to pigpio daemon.")

        self.connection_timeout = connection_timeout
        self.retest_delay = retest_delay
        self.pigpio_connections_info[0] = {"pi": self.pi, "index": 0}

        self._validate_initial_value()
        self._set_initial_state()
        self.connect_to_daemon()

    def _validate_initial_value(self):
        """Validates the initial value of the pin."""
        if self.initial_value not in PinState.values:
            raise ValueError(f"Invalid initial value: {self.initial_value}. Must be OFF or ON.")

    def _set_initial_state(self):
        """Sets the initial state of the pin and logs the result."""
        try:
            self.pi.set_mode(self.pin_number, pigpio.OUTPUT)
            if self.initial_value == PinState.ON:
                self.pi.write(self.pin_number, 1)
            elif self.initial_value == PinState.OFF:
                self.pi.write(self.pin_number, 0)
            else:
                raise ValueError(f"Invalid initial value: {self.initial_value}.")
            self.logger_info(f"Pin {self.pin_number} set to {self.initial_value.name}")
        except pigpio.error as e:
            logger.error(f"Failed to set initial state: {e}")
            raise

    def connect_to_daemon(self):
        """Establishes and maintains a connection to the pigpio daemon."""
        while True:
            try:
                if self.pigpies:
                    for index, info in self.pigpio_connections_info.items():
                        if self.pi == info["pi"]:
                            logger.info(f"Using pigpio connection {index}")
                            break
                    else:
                        logger.warning(f"pigpio connection {index} not found. Attempting to reconnect.")
                        self.pigpio_connections_info[0] = {"pi": self.pi, "index": 0} # Reconnect to the first connection if lost

                if self.pi.connected:
                    return  # Exit if already connected

                self.pi.set_mode(self.pin_number, pigpio.INPUT)  # Set to input while connecting
                time.sleep(self.retest_delay)
                self.pi.set_mode(self.pin_number, pigpio.OUTPUT)  # Switch to output after connection
                time.sleep(self.retest_delay)
                self.pi.stop() # Stop and restart pigpio
                time.sleep(self.connection_timeout)

            except pigpio.error as e:
                logger.error(f"pigpio connection error: {e}")
                time.sleep(self.connection_timeout)
            except Exception as e:
                logger.error(f"Unexpected error during connection: {e}")
                time.sleep(self.connection_timeout)

    def set_value(self, value: PinState):
        """
        Sets the state of the GPIO pin.

        Args:
            value (PinState): The desired state (OFF or ON).

        Raises:
            ValueError: If the provided value is not a valid PinState.
            ConnectionError: If a connection to pigpio is lost while setting the value.
        """
        self._validate_value(value)

        if value == self.initial_value:
            return

        try:
            self._apply_state(value)
            self.logger_info(f"Pin {self.pin_number} set to {value.name}")
        except pigpio.error as e:
            logger.error(f"Failed to set pin {self.pin_number} to {value.name}: {e}")
            raise ConnectionError(f"Lost connection to pigpio: {e}")

    def _apply_state(self, value: PinState):
        """Applies the specified state to the pin, respecting pigpio connections."""
        if value == PinState.ON:
            self.pi.write(self.pin_number, 1)
        elif value == PinState.OFF:
            self.pi.write(self.pin_number, 0)
        else:
            raise ValueError(f"Invalid state: {value}")

    def _validate_value(self, value: PinState):
        """Validates the provided value."""
        if value not in PinState.values:
            raise ValueError(f"Invalid value: {value}. Must be ON or OFF.")

    def get_state(self) -> PinState:
        """
        Returns the current state of the GPIO pin.

        Returns:
            PinState: The current state (OFF or ON).
        """
        try:
            if self.pigpies:
                return self._get_pigpio_value_from_single_connection()
            else:
                return self._get_pigpio_value_from_all_connections()[0]
        except (IndexError, KeyError) as e:
            logger.error(f"Failed to get state: {e}")
            raise

    def get_states(self) -> list[PinState]:
        """
        Returns a list of the current and previous states of the GPIO pin.

        Returns:
            list[PinState]: A list containing the current and previous states.
        """
        try:
            if self.pigpies:
                return self._get_pigpio_values_from_single_connection()
            else:
                return self._get_pigpio_values_from_all_connections()
        except (IndexError, KeyError) as e:
            logger.error(f"Failed to get states: {e}")
            raise

    def logger_info(self, message: str):
        """
        Logs an info message with a timestamp.

        Args:
            message (str): The message to log.
        """
        logger.info(message)

    def logger_debug(self, message: str):
        """
        Logs a debug message with a timestamp.

        Args:
            message (str): The message to log.
        """
        logger.debug(message)

    def close(self):
        """
        Shuts down the pin, disconnecting from pigpio and setting the pin to INPUT.
        """
        try:
            if self.pigpies:
                for connection in self.pigpio_connections_info.values():
                    connection["pi"].stop()
            else:
                self.pi.stop()
            self.pi = None
            self.pigpio_connections_info = {}
            self.logger_info("Pin set to INPUT and closed.")
        except Exception as e:
            logger.error(f"Error closing pin: {e}")


def main():
    """
    Main entry point demonstrating the OutputPin class.
    """
    pin = OutputPin(17, PinState.ON)
    try:
        while True:
            pin.set_value(PinState.OFF)
            time.sleep(0.5)
            pin.set_value(PinState.ON)
            time.sleep(0.5)
    except KeyboardInterrupt:
        logger.info("Exiting...")
    finally:
        pin.close()


if __name__ == "__main__":
    main()

