#!/usr/bin/env python3

"""
A Rainbow HAT demo demonstrating a binary-coded decimal (BCD) system
using touchpads, a 14-segment display, and an APA102 LED strip.
"""

import time
import signal
import sys
import logging
from gpiozero import DigitalInputDevice, DigitalOutputDevice
from adafruit_display.i2c.ht16k33 import HT16K33
from adafruit_display.i2c.apagestrip import APA102
from adafruit_buzzer import Adafruit_Buzzer
from rainbowhat import RainbowHAT as RH

# Configure logging
logging.basicConfig(level=logging.INFO, format='%(asctime)s - %(levelname)s - %(message)s')

# Constants
NUM_BITS = 3
MIDDLE_C = 60
DIM_WHITE = 0.2

# Initialize components
try:
    buzzer = Adafruit_Buzzer(13)
    hat = RH()
    strip = APA102(10, 11)
    display = HT16K33(0x70)
    bit_states = [False] * NUM_BITS  # Initialize all bits to False (0)
    hat.set_7segment_display(0x06) # Set segment remap config
except Exception as e:
    logging.error(f"Initialization error: {e}")
    sys.exit(1)


def display_value(value):
    """Displays the value on the 14-segment display."""
    try:
        display.clear()
        display.set_data(0x00)
        digits = [value // 2, (value % 2) * 4, (value // 4) % 2 * 2, value % 2 * 2, 0, 0, 0]
        for i in range(4):
            if digits[i] > 0:
                display.set_digit(i, 0xFF, 0xFF, 0xFF)
            else:
                display.set_digit(i, 0x00, 0x00, 0x00)
    except Exception as e:
        logging.error(f"Display error: {e}")


def update_led_strip(value):
    """Updates the APA102 LED strip."""
    try:
        if value == 0:
            strip.set_all(0)
        elif value == 7:
            for i in range(7):
                strip.set_pixel(i, 0xFF, 0, 0)  # White
        else:
            strip.set_pixel(value, 0xFF, 0, 0)  # Red for bit 0, Green for bit 1, Blue for bit 2
    except Exception as e:
        logging.error(f"LED strip error: {e}")


def play_tone(value):
    """Plays a tone on the buzzer."""
    try:
        buzzer.play(MIDDLE_C + value)
    except Exception as e:
        logging.error(f"Buzzer error: {e}")


@hat.touch.when_pressed()
def handle_touch(channel):
    """Handles a touch event."""
    try:
        bit_states[channel.value] = not bit_states[channel.value]
        logging.info(f"Touch detected on bit {channel.value}, new state: {bit_states}")
        display_value(bit_states[0] * 2 + bit_states[1] * 4 + bit_states[2])
        update_led_strip(bit_states[0] * 2 + bit_states[1] * 4 + bit_states[2])
        play_tone(bit_states[0] * 2 + bit_states[1] * 4 + bit_states[2])
    except Exception as e:
        logging.error(f"Touch handling error: {e}")


def main():
    """Main function."""
    logging.info("Starting BCD demo")
    try:
        signal.pause()
    except KeyboardInterrupt:
        logging.info("Exiting BCD demo")
    finally:
        hat.set_7segment_display(0x00)
        display.clear()
        strip.set_all(0)
        buzzer.stop()
        sys.exit(0)


if __name__ == "__main__":
    main()

