#!/usr/bin/env python3

import time
import signal
import sys
from gpiozero import DigitalOutputDevice, OutputDevice

# GPIO pin assignments for the A4988 stepper motor driver
DIR_PIN = 20  # Direction control pin
STEP_PIN = 21  # Step pulse enable pin
MS1_PIN = 14  # Microstep resolution select pin 1
MS2_PIN = 15  # Microstep resolution select pin 2
MS3_PIN = 18  # Microstep resolution select pin 3

# Microstep resolution settings (full step is 1/32)
RESOLUTION_FULL = {
    MS1_PIN: False, MS2_PIN: False, MS3_PIN: False
}

RESOLUTION_HALF = {
    MS1_PIN: True, MS2_PIN: False, MS3_PIN: False
}

RESOLUTION_QUARTER = {
    MS1_PIN: False, MS2_PIN: True, MS3_PIN: False
}

RESOLUTION_EIGHTH = {
    MS1_PIN: True, MS2_PIN: True, MS3_PIN: False
}


def setup_gpio():
    """Initialize GPIO pins for the stepper motor driver."""
    try:
        direction = DigitalOutputDevice(DIR_PIN)
        step = DigitalOutputDevice(STEP_PIN)
        resolution_pins = [OutputDevice(pin) for pin in (MS1_PIN, MS2_PIN, MS3_PIN)]
        return direction, step, resolution_pins
    except Exception as e:
        print(f"GPIO setup failed: {e}")
        sys.exit(1)


def set_resolution(resolution_config):
    """Set the microstep resolution of the stepper motor driver."""
    try:
        resolution_pins = (MS1_PIN, MS2_PIN, MS3_PIN)
        for pin, value in resolution_config.items():
            resolution_pins[pin].value = value
    except Exception as e:
        print(f"Resolution setting failed: {e}")


def rotate(direction, steps, delay):
    """Rotate the stepper motor a given number of steps in a direction."""
    step_count = 0
    direction.value = direction
    for _ in range(steps):
        step.value = True
        time.sleep(delay)
        step.value = False
        time.sleep(delay)
        step_count += 1
    print(f"Rotated {steps} steps in direction {direction}")


def main():
    """Main function to control the stepper motor."""
    direction, step, resolution_pins = setup_gpio()
    resolution = RESOLUTION_EIGHTH  # Default resolution

    try:
        while True:
            direction = next((pin for pin in (DIR_PIN, STEP_PIN) if pin.value), None)
            if direction is None:
                print("Error: Direction pin not initialized.")
                continue

            action = input("Enter action (clockwise/counterclockwise/set_resolution/exit): ").lower()

            if action == "clockwise":
                rotate(direction, 800, 0.005/16)  # 800 steps at 1/16 resolution
            elif action == "counterclockwise":
                rotate(direction, 800, 0.005/16)  # 800 steps at 1/16 resolution
            elif action == "set_resolution":
                resolution = RESOLUTION_HALF if action == "set_resolution_half" else RESOLUTION_FULL
                set_resolution(resolution)
            elif action == "exit":
                break
            else:
                print("Invalid action.")

    except KeyboardInterrupt:
        print("\nExiting program.")
    finally:
        step.off()
        direction.off()
        print("GPIO resources released.")


if __name__ == "__main__":
    signal.signal(signal.SIGINT, lambda *args: sys.exit(0))
    main()

