import time
import board
import busio
import adafruit_tcs34725
from PIL import Image
import signal
import sys

# Configuration constants
IMAGE_PATH = 'image.jpg'
I2C_ADDRESS = 0x29
INTEGRATION_TIME_50MS = 50  # ms
GAIN_4X = 4  # Gain setting

# Global flag for graceful shutdown
shutdown_flag = False

def signal_handler(sig, frame):
    """Handles SIGTERM and KeyboardInterrupt signals for graceful shutdown."""
    global shutdown_flag
    shutdown_flag = True
    print("Shutting down gracefully...")

signal.signal(signal.SIGTERM, signal_handler)
signal.signal(signal.SIGINT, signal_handler)

def initialize_i2c():
    """Initializes the I2C bus."""
    try:
        i2c_bus = busio.I2C(board.SCL, board.SDA)
        return i2c_bus
    except Exception as e:
        print(f"Error initializing I2C: {e}")
        return None

def initialize_color_sensor(i2c_bus):
    """Initializes the TCS34725 color sensor."""
    try:
        sensor = adafruit_tcs34725.TCS34725(i2c_bus, address=I2C_ADDRESS)
        sensor.integration_time = INTEGRATION_TIME_50MS
        sensor.gain = GAIN_4X
        return sensor
    except Exception as e:
        print(f"Error initializing TCS34725 sensor: {e}")
        return None

def get_sensor_color_data(sensor):
    """Reads color data from the TCS34725 sensor."""
    try:
        red, green, blue, clear = sensor.color_rgb_bytes
        return red, green, blue, clear
    except Exception as e:
        print(f"Error reading sensor data: {e}")
        return 0, 0, 0, 0

def find_dominant_image_color(image_path):
    """Identifies the dominant color in an image."""
    try:
        image = Image.open(image_path)
        resized_image = image.resize((100, 100))
        color_counts = resized_image.getcolors(10000)
        if color_counts:
            dominant_color = max(color_counts, key=lambda item: item[0])[1]
            return dominant_color
        else:
            print("No colors found in the image.")
            return (0, 0, 0)
    except FileNotFoundError:
        print(f"Error: Image file not found at {image_path}")
        return (0, 0, 0)
    except Exception as e:
        print(f"Error processing image: {e}")
        return (0, 0, 0)

def main():
    """Main function to read color data and identify dominant color."""
    global shutdown_flag

    i2c_bus = initialize_i2c()
    if i2c_bus is None:
        sys.exit(1)

    color_sensor = initialize_color_sensor(i2c_bus)
    if color_sensor is None:
        sys.exit(1)

    try:
        while not shutdown_flag:
            red, green, blue, clear = get_sensor_color_data(color_sensor)
            print(f"Sensor: R={red}, G={green}, B={blue}, Clear={clear}")
            dominant_image_color = find_dominant_image_color(IMAGE_PATH)
            print(f"Image: R={dominant_image_color}, G={dominant_image_color}, B={dominant_image_color}")
            time.sleep(1)
    finally:
        print("Exiting program.")
        if 'color_sensor' in locals():
            color_sensor.close()
        if 'i2c_bus' in locals():
            i2c_bus.deinit()
        sys.exit(0)

if __name__ == "__main__":
    main()

