base_angle = 90
seek_angle = SEEK_ANGLE
grab_angle = OPEN_GRAB_ANGLE
drop_angle = DROP_ANGLE

# Initialize PCA9685
try:
    pwm = PCA9685(busnum=1, address=0x40)
