        logging.error(f"Invalid servo channel: {channel}. Must be between 0 and {num_servos - 1}.")
        return
    if not 0 <= target_angle <= servo_ranges[channel]:
        logging.warning(f"Target angle {target_angle} for servo {channel} is out of range. Clamping to range.")
        target_angle = max(servo_ranges[channel][0], min(target_angle, servo_ranges[channel][1]))

    current_angle = get_servo_angle(channel)
    if current_angle != target_angle:
        for angle in range(current_angle, target_angle, step_size):
            set_servo_angle(channel, angle)
            time.sleep(delay)
        set_servo_angle(channel, target_angle)


