import time
import board
import busio
import adafruit_seesaw.seesaw
import RPi.GPIO as GPIO

# Configuration
PUMP_GPIO_PIN = 17
DRY_SOIL_THRESHOLD = 500
READ_INTERVAL_SECONDS = 10

def initialize_i2c():
    """Initialize the I2C bus."""
    try:
        return busio.I2C(board.SCL, board.SDA)
    except Exception as e:
        print(f"Error initializing I2C: {e}")
        return None

def initialize_soil_sensor(i2c_bus):
    """Initialize the soil moisture sensor."""
    try:
        return adafruit_seesaw.seesaw.Seesaw(i2c_bus, addr=0x36, capacitive=True)
    except Exception as e:
        print(f"Error initializing soil sensor: {e}")
        return None

def initialize_gpio(pump_pin):
    """Initialize the GPIO pin for the water pump."""
    GPIO.setmode(GPIO.BCM)
    GPIO.setup(pump_pin, GPIO.OUT)
    GPIO.output(pump_pin, GPIO.LOW)  # Ensure pump is off initially

def read_soil_moisture(sensor):
    """Read the soil moisture level from the sensor."""
    try:
        return sensor.moisture_read()
    except Exception as e:
        print(f"Error reading soil moisture: {e}")
        return None

def control_water_pump(pump_pin, moisture_level, threshold):
    """Control the water pump based on the soil moisture level."""
    if moisture_level is not None:
        if moisture_level < threshold:
            GPIO.output(pump_pin, GPIO.HIGH)  # Turn pump ON
            pump_status = "ON"
        else:
            GPIO.output(pump_pin, GPIO.LOW)  # Turn pump OFF
            pump_status = "OFF"
    else:
        pump_status = "UNKNOWN"
    return pump_status

def main():
    """Main function to monitor soil moisture and control the water pump."""
    i2c_bus = initialize_i2c()
    if i2c_bus is None:
        return

    soil_sensor = initialize_soil_sensor(i2c_bus)
    if soil_sensor is None:
        return

    initialize_gpio(PUMP_GPIO_PIN)

    try:
        while True:
            moisture = read_soil_moisture(soil_sensor)
            pump_state = control_water_pump(PUMP_GPIO_PIN, moisture, DRY_SOIL_THRESHOLD)

            print(f"Soil Moisture: {moisture}, Pump: {pump_state}")
            time.sleep(READ_INTERVAL_SECONDS)

    except KeyboardInterrupt:
        print("Exiting program...")
    except Exception as e:
        print(f"An unexpected error occurred: {e}")
    finally:
        GPIO.output(PUMP_GPIO_PIN, GPIO.LOW)  # Ensure pump is off
        GPIO.cleanup()
        i2c_bus.deinit()
        print("GPIO and I2C resources cleaned up.")

if __name__ == "__main__":
    main()

