    """Handle a POST request to toggle the relay state."""
    try:
        # Read the JSON payload from the request body
        request_data = request.get_json()

        # Check if the request is valid JSON
        if not request_data or 'state' not in request_data:
            return jsonify({'error': 'Invalid request: missing state'}), 400

        # Apply the requested relay state
        if request_data['state'] == 'on':
            relay.on()
        else:
