import smbus2
import contextlib

# I2C device helper for Raspberry Pi
# Subcategory: I2C device wrapper

class I2CDevice(contextlib.AbstractContextManager):
    """Context manager for an I2C device."""

    def __init__(self, address, bus_number=1):
        """
        Initialize the I2C device.

        Args:
            address: The I2C address of the device.
            bus_number: The I2C bus number (default: 1).
        """
        self.address = address
        self.bus_number = bus_number
        self.bus = smbus2.SMBus(bus_number)

    def __enter__(self):
        """Return the I2C device context."""
        return self

    def __exit__(self, exc_type, exc_value, traceback):
        """Close the I2C bus on exit."""
        if self.bus.is_device:
            self.bus.close()

    def write_byte(self, register, value):
        """
        Write a single byte to the given register.

        Args:
            register: The register to write to.
            value: The byte value to write.

        Raises:
            RuntimeError: If the device does not acknowledge the address.
        """
        try:
            if self.bus.is_device:
                self.bus.write_byte_data(self.address, register, value)
            else:
                self.bus.write_byte_data(self.address, register, value)
        except OSError as bus_error:
            if "No device present" not in str(bus_error):
                raise RuntimeError("I2C device not acknowledging address: {}".format(bus_error)) from bus_error

    def read_byte(self, register):
        """
        Read a single byte from the given register.

        Args:
            register: The register to read from.

        Returns:
            The byte value read from the device.

        Raises:
            RuntimeError: If the device does not acknowledge the address.
        """
        try:
            if self.bus.is_device:
                return self.bus.read_byte_data(self.address, register)
            else:
                return self.bus.read_byte_data(self.address, register)
        except OSError as bus_error:
            if "No device present" not in str(bus_error):
                raise RuntimeError("I2C device not acknowledging address: {}".format(bus_error)) from bus_error


if __name__ == "__main__":
    DEVICE_ADDRESS = 0x40
    try:
        with I2CDevice(DEVICE_ADDRESS) as device:
            device.write_byte(0x00, 0x55)
            device.read_byte(0x00)
    except RuntimeError as error:
        print("Error accessing I2C device: {}".format(error))
    finally:
        # The smbus2.SMBus instance is automatically closed on exit of __exit__
        pass

