#!/usr/bin/python3
# -*- coding: utf-8 -*-

"""
DS1338 Real-Time Clock Driver for Raspberry Pi.

This module provides a robust and performant interface to the DS1338 RTC
using the smbus2 library. It offers comprehensive error handling, optimized
performance, and adheres to best practices for hardware interaction.
"""

import smbus2
import time
import logging
import signal
import sys

# Configure logging
logging.basicConfig(level=logging.INFO, format='%(asctime)s - %(levelname)s - %(message)s')
logger = logging.getLogger(__name__)

# Register addresses for the DS1338
REGISTERS = {
    "seconds": 0x00,
    "minutes": 0x01,
    "hours": 0x02,
    "day": 0x03,
    "date": 0x04,
    "month": 0x05,
    "year": 0x06,
    "control": 0x07,
}

# BCD constants
BCD_ONES = 0x06
BCD_TWOS = 0x07

class DS1338:
    """Driver for the DS1338 Real-Time Clock."""

    def __init__(self, i2c_bus=1, i2c_address=0x68, century=21):
        """
        Initialize the DS1338 driver.

        Args:
            i2c_bus (int): The I2C bus number.
            i2c_address (int): The I2C address of the RTC.
            century (int): The century (00-99).
        """
        self.i2c_bus = i2c_bus
        self.i2c_address = i2c_address
        self._century = century
        self._last_write_error = None
        self._bus = None

    def _validate_register(self, register):
        """Validate register address."""
        if not isinstance(register, int) or register < 0 or register > 15:
            raise ValueError("Register must be an integer between 0 and 15")

    def _bcd_to_int(self, bcd):
        """Convert BCD to integer."""
        return (bcd >> 4) * 10 + (bcd & 0x0F)

    def _int_to_bcd(self, integer):
        """Convert integer to BCD."""
        tens = integer // 10
        units = integer % 10
        return (tens * 0x06) + (units * 0x01)

    def _read_register(self, register):
        """Read a byte from the specified register."""
        self._validate_register(register)
        try:
            return self._bus.read_byte_data(self.i2c_address, register)
        except IOError as e:
            logger.error(f"I2C read error: {e}")
            raise OSError(f"Failed to read register 0x{register:02X}: {e}") from e

    def _write_register(self, register, value):
        """Write a byte to the specified register."""
        self._validate_register(register)
        try:
            self._bus.write_byte_data(self.i2c_address, register, value)
        except IOError as e:
            logger.error(f"I2C write error: {e}")
            raise OSError(f"Failed to write to register 0x{register:02X}: {e}") from e


    def _read_time_register(self, register):
        """Read and convert a time register (seconds, minutes, etc.)."""
        value = self._read_register(register)
        if register == REGISTERS["seconds"]:
            return self._bcd_to_int(value)
        elif register == REGISTERS["minutes"]:
            return self._bcd_to_int(value)
        elif register == REGISTERS["hours"]:
            # Handle two-digit hours (00-23)
            value = (value & 0x3F)  # Mask off century bit
            if value >= 10:
                return self._bcd_to_int(value - 10)  # Convert to BCD
            else:
                return value
        elif register == REGISTERS["day"]:
            return self._bcd_to_int(value)
        elif register == REGISTERS["date"]:
            return self._bcd_to_int(value)
        elif register == REGISTERS["month"]:
            return self._bcd_to_int(value)
        elif register == REGISTERS["year"]:
            # Handle four-digit years (00-99)
            value = self._bcd_to_int(value)
            if value >= 10000:
                return self._bcd_to_int(value - 10000)  # Convert to BCD
            else:
                return value
        else:
            raise ValueError(f"Invalid register: {register}")


    def read_all(self):
        """Read all time and date registers."""
        try:
            year = self._read_time_register(REGISTERS["year"])
            month = self._read_time_register(REGISTERS["month"])
            date = self._read_time_register(REGISTERS["date"])
            day = self._read_time_register(REGISTERS["day"])
            hours = self._read_time_register(REGISTERS["hours"])
            minutes = self._read_time_register(REGISTERS["minutes"])
            seconds = self._read_time_register(REGISTERS["seconds"])
            return (year, month, date, day, hours, minutes, seconds)
        except OSError as e:
            logger.error(f"I2C read error: {e}")
            raise

    def read_datetime(self, century=21):
        """
        Read the current time and return a datetime object.

        Args:
            century (int): The century (00-99).

        Returns:
            datetime: A datetime object representing the current time.

        Raises:
            OSError: If a read error occurs.
        """
        try:
            year, month, date, day, hours, minutes, seconds = self.read_all()
            year = (century - 1) * 100 + year  # Correct year calculation
            return datetime(year, month, date, hours, minutes, seconds)
        except OSError as e:
            raise OSError(f"Failed to read datetime: {e}") from e


    def write_all(self, seconds=None, minutes=None, hours=None, day=None, date=None, month=None, year=None):
        """
        Write all time and date registers.

        Args:
            seconds (int, optional): The seconds value. Defaults to None.
            minutes (int, optional): The minutes value. Defaults to None.
            hours (int, optional): The hours value. Defaults to None.
            day (int, optional): The day value. Defaults to None.
            date (int, optional): The date value. Defaults to None.
            month (int, optional): The month value. Defaults to None.
            year (int, optional): The year value. Defaults to None.

        Raises:
            ValueError: If an invalid register is written to.
            OSError: If a write error occurs.
        """

        if seconds is not None:
            self._last_write_error = self._write_register(REGISTERS["seconds"], self._int_to_bcd(seconds))
        if minutes is not None:
            self._last_write_error = self._write_register(REGISTERS["minutes"], self._int_to_bcd(minutes))
        if hours is not None:
            # Ensure hours are within 0-23
            self._last_write_error = self._write_register(REGISTERS["hours"], self._int_to_bcd(hours % 100))
        if day is not None:
            self._last_write_error = self._write_register(REGISTERS["day"], self._int_to_bcd(day))
        if date is not None:
            self._last_write_error = self._write_register(REGISTERS["date"], self._int_to_bcd(date))
        if month is not None:
            self._last_write_error = self._write_register(REGISTERS["month"], self._int_to_bcd(month))
        if year is not None:
            # DS1338 expects the year to be written as two BCD digits
            self._last_write_error = self._write_register(REGISTERS["year"], self._int_to_bcd(year % 100))

        if self._last_write_error is not None:
            logger.error(f"DS1338 write error: {self._last_write_error}")


def initialize_rtc(i2c_bus=1, i2c_address=0x68):
    """
    Initialize the DS1338 RTC.

    Args:
        i2c_bus (int): The I2C bus number.
        i2c_address (int): The I2C address of the RTC.

    Returns:
        DS1338: The initialized DS1338 object.

    Raises:
        OSError: If the RTC is not present.
    """
    try:
        bus = smbus2.SMBus(i2c_bus)
        rtc = DS1338(i2c_bus, i2c_address)
        # Check if the RTC is present by reading the control register
        if bus.read_byte_data(i2c_address, REGISTERS["control"]) & 0x10:
            raise OSError(f"DS1338 not found at address 0x{i2c_address:02X}")
        return rtc
    except (OSError, ValueError) as e:
        logger.error(f"Failed to initialize DS1338: {e}")
        raise


def shutdown_handler(signum, frame):
    """Shutdown handler to gracefully exit the application."""
    logger.info("Shutting down...")
    if 'rtc' in locals():
        rtc.bus.close()
    sys.exit(0)


def main():
    """Main function to demonstrate the DS1338 driver."""
    i2c_bus = 1
    i2c_address = 0x68
    century = 21

    rtc = None
    try:
        rtc = initialize_rtc(i2c_bus, i2c_address)
        logger.info(f"DS1338 initialized on I2C bus {i2c_bus} at address 0x{i2c_address:02X}")

        while True:
            now = rtc.read_datetime(century)
            logger.info(f"Current time: {now.strftime('%Y-%m-%d %H:%M:%S')}")
            time.sleep(60)  # Read every minute

    except (OSError, ValueError) as e:
        logger.error(f"Failed to initialize DS1338: {e}")
        sys.exit(1)
    except KeyboardInterrupt:
        logger.info("Exiting...")
    finally:
        if rtc:
            rtc.bus.close()


if __name__ == "__main__":
    signal.signal(signal.SIGINT, shutdown_handler)
    signal.signal(signal.SIGTERM, shutdown_handler)
    main()

