        bus = smbus2.SMBus(i2c_bus)
        rtc = DS1338(i2c_bus, i2c_address)
        # Check if the RTC is present by reading the control register
        if bus.read_byte_data(i2c_address, REGISTERS["control"]) & 0x10:
            raise OSError(f"DS1338 not found at address 0x{i2c_address:02X}")
        return rtc
    except (OSError, ValueError) as e:
        logger.error(f"Failed to initialize DS1338: {e}")
        raise


def shutdown_handler(signum, frame):
    """Shutdown handler to gracefully exit the application."""
    logger.info("Shutting down...")
    if 'rtc' in locals():
        rtc.bus.close()
    sys.exit(0)


def main():
    """Main function to demonstrate the DS1338 driver."""
    i2c_bus = 1
    i2c_address = 0x68
    century = 21

    rtc = None
    try:
        rtc = initialize_rtc(i2c_bus, i2c_address)
        logger.info(f"DS1338 initialized on I2C bus {i2c_bus} at address 0x{i2c_address:02X}")

        while True:
            now = rtc.read_datetime(century)
            logger.info(f"Current time: {now.strftime('%Y-%m-%d %H:%M:%S')}")
            time.sleep(60)  # Read every minute

    except (OSError, ValueError) as e:
        logger.error(f"Failed to initialize DS1338: {e}")
        sys.exit(1)
    except KeyboardInterrupt:
        logger.info("Exiting...")
    finally:
        if rtc:
            rtc.bus.close()


if __name__ == "__main__":
    signal.signal(signal.SIGINT, shutdown_handler)
    signal.signal(signal.SIGTERM, shutdown_handler)
    main()

