# water meter controller for a Raspberry Pi
# Reads flow rate from a serial sensor and controls a GPIO relay
import serial
import time
from gpiozero import OutputDevice

# Serial port configuration for the water meter
SERIAL_PORT = "/dev/ttyUSB0"
BAUD_RATE = 9600
TIMEOUT = 1
# GPIO pin driving the water meter relay
RELAY_PIN = 17
FLOW_THRESHOLD = 10.0


def open_serial_port(port, baudrate, timeout):
    """Open and return a serial port object."""
    try:
        return serial.Serial(port, baudrate, timeout=timeout)
    except serial.SerialException as error:
        print("Could not open serial port:", error)
        return None


def read_flow_rate(serial_port):
    """Read and parse a flow rate line from the serial port."""
    try:
        line = serial_port.readline().decode("ascii", errors="replace").strip()
        if line:
            return float(line)
        return None
    except ValueError:
        print("Received non-numeric data from serial port")
        return None


def control_relay(relay_pin, flow_rate, threshold):
    """Drive the GPIO relay based on the flow rate threshold."""
    if flow_rate > threshold:
        # Activate the relay if flow exceeds the threshold
        relay_pin.on()
    else:
        # Deactivate the relay for normal flow
        relay_pin.off()


def main():
    """Main function to read flow rate and control the relay."""
    serial_connection = open_serial_port(SERIAL_PORT, BAUD_RATE, TIMEOUT)
    if not serial_connection:
        return

    relay = OutputDevice(RELAY_PIN)

    try:
        while True:
            flow_value = read_flow_rate(serial_connection)
            if flow_value is not None:
                print("Flow rate:", flow_value, "L/min")
                control_relay(relay, flow_value, FLOW_THRESHOLD)
            time.sleep(1)
    except KeyboardInterrupt:
        print("Stopping water meter controller")
    finally:
        # Close the serial port and release GPIO resources
        serial_connection.close()
        relay.close()


if __name__ == "__main__":
    main()

