import serial
import time
import logging
import signal
import sys
from datetime import datetime

# Configure logging for the healthcare monitoring system
logging.basicConfig(level=logging.INFO, format="%(asctime)s %(message)s")

# Serial port configuration for the pulse oximeter sensor
SERIAL_PORT = "/dev/ttyUSB0"
BAUD_RATE = 9600
TIMEOUT = 1

# Log file for storing health readings
LOG_FILE = "health_readings_log.txt"


def read_pulse_data(serial_port):
    """Read a line of comma-separated heart rate and SpO2 values from the serial port."""
    try:
        line = serial_port.readline().decode("ascii", errors="replace").strip()
        if line:
            return line.split(",")
        return None
    except Exception as read_error:
        logging.error("Error reading serial data: %s", read_error)
        return None


def parse_pulse_values(raw_values):
    """Parse comma-separated heart rate and SpO2 values into integers."""
    if raw_values:
        try:
            heart_rate = int(raw_values[0])
            spo2 = int(raw_values[1])
            return heart_rate, spo2
        except ValueError as parse_error:
            logging.error("Error parsing pulse values: %s", parse_error)
            return None, None
    return None, None


def log_reading(heart_rate, spo2):
    """Append a timestamped health reading to the log file."""
    timestamp = datetime.now().isoformat()
    log_entry = f"{timestamp},{heart_rate},{spo2}\n"
    try:
        with open(LOG_FILE, "a") as log_handle:
            log_handle.write(log_entry)
        logging.info("Logged reading: %s", log_entry.strip())
    except IOError as log_error:
        logging.error("Error writing to log file: %s", log_error)


def main_loop(serial_port):
    """Continuously read, parse, and log pulse oximeter data."""
    try:
        while True:
            pulse_data = read_pulse_data(serial_port)
            if pulse_data:
                heart_rate, spo2 = parse_pulse_values(pulse_data)
                if heart_rate is not None and spo2 is not None:
                    log_reading(heart_rate, spo2)
            time.sleep(0.1)
    except KeyboardInterrupt:
        logging.info("Stopping pulse monitoring")
    except Exception as main_error:
        logging.error("Main loop error: %s", main_error)
    finally:
        serial_port.close()
        logging.info("Serial port closed")


if __name__ == "__main__":
    # Set up signal handler for graceful shutdown
    signal.signal(signal.SIGINT, lambda *args: sys.exit(0))
    signal.signal(signal.SIGTERM, lambda *args: sys.exit(0))
    try:
        # Open the serial port and start the main loop
        serial_connection = serial.Serial(SERIAL_PORT, BAUD_RATE, timeout=TIMEOUT)
        main_loop(serial_connection)
    except serial.SerialException as serial_error:
        logging.error("Could not open serial port: %s", serial_error)
    except Exception as startup_error:
        logging.error("Startup error: %s", startup_error)
    finally:
        logging.info("Healthcare monitoring system stopped")

