from flask import Flask, render_template, Response, request, jsonify
import json
import time
import serial
import os

app = Flask(__name__)

# Serial port configuration for the instrument
SERIAL_PORT = '/dev/ttyUSB0'
SERIAL_BAUDRATE = 9600

# In-memory data store for the Flask app
DATA_STORE = [{"id": 1, "name": "Item 1", "done": False},
              {"id": 2, "name": "Item 2", "done": False}]

def open_serial_port():
    """Opens and configures the serial port for communication with the instrument."""
    try:
        ser = serial.Serial(SERIAL_PORT, SERIAL_BAUDRATE, timeout=1)
        time.sleep(2)  # Allow time for the serial connection to stabilize
        return ser
    except serial.SerialException as e:
        print(f"Error opening serial port: {e}")
        return None

def close_serial_port(ser):
    """Closes the serial port."""
    if ser and ser.is_open:
        ser.close()

@app.route('/version', methods=['GET'])
def get_instrument_version():
    """Retrieves the SCPI version string from the connected instrument."""
    ser = open_serial_port()
    if not ser:
        return Response("Error: Could not open serial port.\n", mimetype='text/plain', status=503)

    try:
        ser.write(b"*IDN?\n")
        time.sleep(0.1)  # Allow time for the instrument to respond
        response = ser.readline().decode('utf-8', errors='ignore').strip()
        close_serial_port(ser)
        return Response(response + '\n', mimetype='text/html')
    except serial.SerialException as e:
        print(f"Error reading from serial port: {e}")
        close_serial_port(ser)
        return Response("Error: Could not read from serial port.\n", mimetype='text/plain', status=503)

@app.route('/getdata', methods=['GET'])
def get_all_data():
    """Returns the entire data store as a JSON response."""
    return jsonify(DATA_STORE)

@app.route('/getset/<int:item_id>', methods=['GET'])
def get_item(item_id):
    """Retrieves a specific item from the data store by ID."""
    item = next((item for item in DATA_STORE if item['id'] == item_id), None)
    if item:
        return jsonify(item)
    else:
        return Response("Error: Item not found.\n", mimetype='text/plain', status=404)

@app.route('/getpost/<int:item_id>/<name>', methods=['GET'])
def append_item(item_id, name):
    """Appends a new item to the data store via a GET request."""
    new_item = {
        "id": (DATA_STORE[-1]['id'] + 1 if DATA_STORE else 1),
        "name": name,
        "done": False
    }
    DATA_STORE.append(new_item)
    return jsonify(DATA_STORE)

@app.route('/postjson', methods=['POST'])
def post_json():
    """Handles POST requests with JSON or form-encoded data."""
    if request.headers.get('Content-Type') == 'application/json':
        try:
            data = request.get_json()
            if not isinstance(data, list):
                raise ValueError("Invalid JSON format. Expecting a list of items.")
            for item in data:
                item['id'] = (DATA_STORE[-1]['id'] + 1 if DATA_STORE else 1)
                DATA_STORE.append(item)
            return jsonify(DATA_STORE)
        except ValueError as e:
            return Response(str(e) + '\n', mimetype='text/plain', status=400)
    elif request.headers.get('Content-Type') == 'multipart/form-encoded':
        new_item = request.form
        new_item['id'] = (DATA_STORE[-1]['id'] + 1 if DATA_STORE else 1)
        DATA_STORE.append(new_item)
        return jsonify(DATA_STORE)
    else:
        return Response("Unsupported Content-Type.\n", mimetype='text/plain', status=415)

@app.route('/postjson/<path:path]', methods=['POST'])
def post_json_file(path):
    """Handles POST requests to upload files."""
    if request.headers.get('Content-Type') == 'application/json':
        try:
            data = request.get_json()
            # In a real application, you would handle the uploaded file here.
            # For this example, we'll just log the request.
            print(f"Uploaded {path} with data: {data}")
            return Response("File uploaded successfully.\n", mimetype='text/plain', status=200)
        except ValueError as e:
            return Response(str(e) + '\n', mimetype='text/plain', status=400)
    else:
        return Response("Unsupported Content-Type.\n", mimetype='text/plain', status=415)

@app.route('/', methods=['GET'])
def index_page():
    """Returns the main index page with links to the API endpoints."""
    return render_template('index.html')

if __name__ == '__main__':
    # Seed the data store with some initial items
    DATA_STORE.extend([
        {"id": 3, "name": "Item 3", "done": False},
        {"id": 4, "name": "Item 4", "done": False}
    ])
    ser = open_serial_port()
    if not ser:
        print("Failed to open serial port. Exiting.")
        exit(1)

    app.run(host='0.0.0.0', port=5000, debug=False)

